// Workbench Pro: the user's customization folder (<userData>/workbench-custom/).
//
//   user.css        extra styles for the workbench page (hot-swapped)
//   settings.json   editor / terminal / layout settings (validated in the page, applied live)
//   plugins/*.js    plugins (classic scripts run inside the workbench page, see API.md)
//   AGENTS.md       how coding agents should change all of the above (created once, user-editable)
//   API.md          the plugin API reference (regenerated by Meridian on every start)
//   .history/       automatic snapshots of the three above, for one-click revert
//
// Trust: plugins run in the workbench page, which can open terminals and edit project files. That is
// the point (agents extend the IDE live), so the safety net is visibility (active plugins are listed,
// each can be switched off), Safe Mode (nothing from this folder loads), and snapshots (revert).
// The folder is served to the internal session only, read-only, at meridian://workbench/custom/,
// with real-path checks so symlinks can't expose anything outside it.

const fs = require('fs');
const fsp = fs.promises;
const path = require('path');

const MAX_FILE = 2 * 1024 * 1024;
const MAX_PLUGINS = 50;
const KEEP_SNAPSHOTS = 40;
const SERVE = /^(user\.css|plugins\/[A-Za-z0-9._-]+(\/[A-Za-z0-9._-]+)*\.(js|css|json|svg|png))$/;
const PLUGIN_FILE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,80}\.js$/;

const DEFAULT_SETTINGS = {
  editor: { fontSize: 13, fontFamily: '', lineHeight: 20, minimap: false, wordWrap: 'off', tabSize: 2, theme: 'auto' },
  terminal: { fontSize: 12.5, fontFamily: '', lineHeight: 1.15 },
  layout: { treeWidth: 240, terminalHeight: '38%', sidePanelWidth: 320, showTree: true },
  ui: { accent: '' },
};

const USER_CSS = `/* Workbench user styles — loaded after the built-in styles, hot-reloaded on save.
 * Useful variables: --space (accent), --surface, --surface-2, --text, --text-muted, --border,
 * --mono, --font, --tree-w, --term-h. Example:
 *
 *   #topbar { background: color-mix(in srgb, var(--space) 6%, var(--surface)); }
 */
`;

const EXAMPLE_PLUGIN = `// Example plugin — copy this file into plugins/ to try it. Full reference: ../API.md
workbenchPlugin({ id: 'hello', name: 'Hello button' }, (api) => {
  api.toolbar.add({
    id: 'hello', label: 'Hello', icon: 'bolt', title: 'Say hello',
    onClick: () => api.toast('Hello from a plugin, ' + (api.project()?.name || 'no project')),
  });
  api.commands.add({ id: 'hello.git-status', title: 'Git: status in a terminal', keybinding: 'Mod+Shift+G', run: () => api.terminal.run('git status') });
});
`;

const API_MD = `# Meridian Workbench — plugin API

> Generated by Meridian on every start. Don't edit; edit AGENTS.md, settings.json, user.css and plugins/ instead.

Plugins are plain JavaScript files in \`plugins/\` (one file = one plugin, loaded in alphabetical
order). They run inside the Workbench page, as classic scripts (no \`import\`, no \`require\`, no
network: the page may only load files from Meridian itself). Every change to this folder is applied
live: CSS and settings instantly, plugins are torn down and loaded again.

## Registering

\`\`\`js
workbenchPlugin({ id: 'deploy', name: 'Deploy button' }, (api) => {
  // add things through api.* — they are removed automatically when the plugin reloads
  return () => { /* optional extra cleanup */ };
});
\`\`\`

## api

| Member | What it does |
| --- | --- |
| \`api.toolbar.add({ id, label, icon?, title?, onClick })\` | Button in the top bar (right of the agent launchers). \`icon\`: one of bolt, play, code, terminal, globe, file, folder, star, pin, layers, shield, lock, reload, search, settings. |
| \`api.commands.add({ id, title, run, keybinding? })\` | Command in the palette (⌘⇧P / Ctrl+Shift+P). \`keybinding\` like \`'Mod+Shift+D'\` (Mod = ⌘ on macOS, Ctrl elsewhere; also Alt, Shift). |
| \`api.keybindings.add('Mod+Alt+T', fn)\` | Bare keybinding. Keys Meridian uses app-wide (⌘T, ⌘L, ⌘W, ⌘D, ⌘S, ⌘J, ⌘1–9, …) never reach the page — prefer Mod+Alt+… or Mod+Shift+… combos. |
| \`api.panels.add({ id, title, icon?, render(el) })\` | Panel in the right side pane. \`render\` gets an empty element; may return a cleanup function. |
| \`api.launchers.add({ id, label, command, mark?, color? })\` | Launcher next to Claude Code / Codex / Shell: opens a shell in the project and runs \`command\`. |
| \`api.terminal.run(command, { title? })\` | Opens a shell in the project and types \`command\` + Enter. Returns a promise. |
| \`api.files.read(rel)\` / \`api.files.write(rel, text)\` / \`api.files.open(rel)\` | Project files (paths relative to the project root). |
| \`api.project()\` | \`{ root, name }\` or \`null\`. |
| \`api.settings()\` | Current effective settings (read-only copy). |
| \`api.on(event, fn)\` | Events: \`'project'\` (project opened), \`'file-open'\` (rel path), \`'file-save'\` (rel path). |
| \`api.toast(text)\` | Small notification. |
| \`api.css(text)\` | Adds a style block (removed when the plugin reloads). |
| \`api.el(tag, props?, ...children)\` | Tiny DOM helper: \`api.el('button', { className: 'btn small', onclick }, 'Go')\`. |

Use \`textContent\` (or \`api.el\`) for any text that comes from files or terminals — never \`innerHTML\`
with data you didn't write.

## settings.json

\`\`\`json
${JSON.stringify(DEFAULT_SETTINGS, null, 2)}
\`\`\`

- \`editor.theme\`: \`"auto"\` (follows the system), \`"light"\`, \`"dark"\`, \`"hc-black"\`, \`"hc-light"\`.
- \`layout.terminalHeight\`: CSS length (\`"40%"\`, \`"320px"\`). \`layout.showTree\`: hide the file tree.
- \`ui.accent\`: hex colour to override the space colour (\`"#d97757"\`), empty = follow the space.

## user.css

Loaded after the built-in styles. Main regions: \`#topbar\`, \`#tree-pane\`, \`#editor-area\`,
\`#term-area\`, \`#side-pane\`, \`#statusbar\`. Variables: \`--space\`, \`--surface\`, \`--surface-2\`,
\`--text\`, \`--text-muted\`, \`--border\`, \`--mono\`, \`--font\`.

## Safety

- Everything here runs with the Workbench's powers (terminals, project files). Only add code you'd
  run yourself.
- The user can switch any plugin off, start in Safe Mode (nothing from this folder loads) and revert
  to any automatic snapshot from the Customize panel.
- Never write API keys or tokens into these files. Secrets live in Meridian's vault and reach
  processes as environment variables.
`;

const AGENTS_MD = `# Workbench customizations — instructions for agents

This folder customizes the Meridian Workbench (the mini IDE you are running in). The user asks for
changes like "make the editor font bigger", "add a deploy button", "show a TODO panel"; you make
them by editing files here. Meridian applies every saved change live — no restart, no build.

Read **API.md** first: it is the exact, current plugin API and settings reference.

## Where to change what

- Font, sizes, theme, layout → \`settings.json\` (keep it valid JSON; unknown keys are ignored).
- Colours, spacing, hiding things → \`user.css\`.
- New buttons, commands, keybindings, panels, launchers → a plugin in \`plugins/<name>.js\`.
  One feature per file, named after the feature (\`plugins/deploy-button.js\`).

## Rules

- Small, focused edits. Don't rewrite files you weren't asked to touch.
- Plugins: classic scripts only (no import/require/fetch to the internet). Use \`textContent\` /
  \`api.el\` for text; never build HTML from file or terminal contents.
- Don't touch \`.history/\` (automatic snapshots) or \`API.md\` (regenerated by Meridian).
- Never put secrets in these files. If a command needs a key, it is already in the environment of
  terminals Meridian starts (ask the user to add it to the vault if it isn't).
- After a change, tell the user what to look at. If something broke, they can revert from the
  Customize panel; you can also restore files from \`.history/<snapshot>/\`.
- \`examples/\` has a working plugin to copy from.
`;

const CLAUDE_MD = '# CLAUDE.md\n\nRead [AGENTS.md](AGENTS.md) and [API.md](API.md) before changing anything here.\n\n@AGENTS.md\n';

class Customizations {
  constructor(root, onChange) {
    this.root = root;
    this.onChange = onChange;
    this.watcher = null;
    this.timer = null;
    this.ensure();
    this.realRoot = fs.realpathSync(root);
    this.watch();
  }

  ensure() {
    fs.mkdirSync(path.join(this.root, 'plugins'), { recursive: true });
    fs.mkdirSync(path.join(this.root, 'examples'), { recursive: true });
    fs.mkdirSync(path.join(this.root, '.history'), { recursive: true });
    const once = (rel, text) => { try { fs.writeFileSync(path.join(this.root, rel), text, { flag: 'wx' }); } catch {} };
    once('user.css', USER_CSS);
    once('settings.json', JSON.stringify(DEFAULT_SETTINGS, null, 2) + '\n');
    once('AGENTS.md', AGENTS_MD);
    once('CLAUDE.md', CLAUDE_MD);
    once('examples/hello-button.js', EXAMPLE_PLUGIN);
    once('.gitignore', '.history/\n');
    try { fs.writeFileSync(path.join(this.root, 'API.md'), API_MD); } catch {}
  }

  inside(abs) { return abs === this.realRoot || abs.startsWith(this.realRoot + path.sep); }

  // meridian://workbench/custom/<rel> -> absolute file, or null. Lexical check here; real-path check in serve().
  fileFor(rel) {
    if (typeof rel !== 'string' || !SERVE.test(rel) || rel.split('/').some((s) => s === '..' || s.startsWith('.'))) return null;
    const abs = path.resolve(this.realRoot, rel);
    return this.inside(abs) ? abs : null;
  }

  async serve(rel) {
    const abs = this.fileFor(rel);
    if (!abs) return null;
    const real = await fsp.realpath(abs).catch(() => null);
    if (!real || !this.inside(real)) return null;
    const st = await fsp.stat(real);
    if (!st.isFile() || st.size > MAX_FILE) return null;
    return fsp.readFile(real);
  }

  async plugins() {
    let names = [];
    try { names = await fsp.readdir(path.join(this.realRoot, 'plugins')); } catch {}
    const out = [];
    for (const name of names.filter((n) => PLUGIN_FILE.test(n)).sort().slice(0, MAX_PLUGINS)) {
      try {
        const real = await fsp.realpath(path.join(this.realRoot, 'plugins', name));
        if (!this.inside(real)) continue;
        const st = await fsp.stat(real);
        if (st.isFile()) out.push({ file: name, mtimeMs: st.mtimeMs, size: st.size });
      } catch {}
    }
    return out;
  }

  async state() {
    let settingsText = '';
    let cssMtime = 0;
    try { settingsText = await fsp.readFile(path.join(this.realRoot, 'settings.json'), 'utf8'); } catch {}
    try { cssMtime = (await fsp.stat(path.join(this.realRoot, 'user.css'))).mtimeMs; } catch {}
    let settings = null;
    let settingsError = null;
    if (settingsText.trim()) { try { settings = JSON.parse(settingsText); } catch (err) { settingsError = err.message; } }
    return { root: this.realRoot, settings, settingsError, cssMtime, plugins: await this.plugins() };
  }

  // ----- watching + snapshots -----

  watch() {
    try {
      this.watcher = fs.watch(this.realRoot, { recursive: true }, (_e, file) => {
        const f = String(file || '').split(path.sep).join('/');
        if (f.startsWith('.history') || f === 'API.md' || f.endsWith('.tmp') || f.endsWith('~')) return;
        clearTimeout(this.timer);
        this.timer = setTimeout(() => this.changed(), 200);
      });
      this.watcher.on('error', () => {});
    } catch (err) { console.warn('workbench: cannot watch customizations', err.message); }
  }

  async changed() {
    try { await this.snapshot('auto'); } catch (err) { console.warn('workbench: snapshot failed', err.message); }
    this.onChange?.();
  }

  // The files a snapshot covers: user.css, settings.json, AGENTS.md, plugins/*.js.
  async collect() {
    const files = {};
    for (const rel of ['user.css', 'settings.json', 'AGENTS.md']) {
      try { const b = await fsp.readFile(path.join(this.realRoot, rel)); if (b.length <= MAX_FILE) files[rel] = b.toString('utf8'); } catch {}
    }
    for (const p of await this.plugins()) {
      if (p.size > MAX_FILE) continue;
      try { files[`plugins/${p.file}`] = await fsp.readFile(path.join(this.realRoot, 'plugins', p.file), 'utf8'); } catch {}
    }
    return files;
  }

  historyDir() { return path.join(this.realRoot, '.history'); }

  async snapshots() {
    let dirs = [];
    try { dirs = (await fsp.readdir(this.historyDir())).filter((d) => /^\d{13}-[a-z]+$/.test(d)).sort().reverse(); } catch {}
    const out = [];
    for (const id of dirs) {
      let files = [];
      try { files = JSON.parse(await fsp.readFile(path.join(this.historyDir(), id, 'manifest.json'), 'utf8')).files || []; } catch {}
      out.push({ id, at: Number(id.slice(0, 13)), reason: id.slice(14), files });
    }
    return out;
  }

  async snapshot(reason) {
    const files = await this.collect();
    const list = await this.snapshots();
    // Skip when nothing changed since the newest snapshot.
    if (list[0]) {
      const prev = await this.readSnapshot(list[0].id).catch(() => null);
      if (prev && JSON.stringify(prev) === JSON.stringify(files)) return list[0].id;
    }
    const id = `${Date.now()}-${reason}`;
    const dir = path.join(this.historyDir(), id);
    await fsp.mkdir(path.join(dir, 'plugins'), { recursive: true });
    for (const [rel, text] of Object.entries(files)) await fsp.writeFile(path.join(dir, rel), text);
    await fsp.writeFile(path.join(dir, 'manifest.json'), JSON.stringify({ files: Object.keys(files) }));
    for (const old of list.slice(KEEP_SNAPSHOTS - 1)) await fsp.rm(path.join(this.historyDir(), old.id), { recursive: true, force: true }).catch(() => {});
    return id;
  }

  async readSnapshot(id) {
    if (!/^\d{13}-[a-z]+$/.test(String(id))) throw new Error('bad snapshot id');
    const dir = path.join(this.historyDir(), id);
    const manifest = JSON.parse(await fsp.readFile(path.join(dir, 'manifest.json'), 'utf8'));
    const files = {};
    for (const rel of manifest.files || []) {
      if (!/^(user\.css|settings\.json|AGENTS\.md|plugins\/[A-Za-z0-9][A-Za-z0-9._-]{0,80}\.js)$/.test(rel)) continue;
      files[rel] = await fsp.readFile(path.join(dir, rel), 'utf8');
    }
    return files;
  }

  // Restore a snapshot: the current state is snapshotted first, so a revert can itself be reverted.
  async restore(id) {
    const files = await this.readSnapshot(id);
    await this.snapshot('before-revert');
    for (const p of await this.plugins()) if (!(`plugins/${p.file}` in files)) await fsp.rm(path.join(this.realRoot, 'plugins', p.file), { force: true });
    for (const [rel, text] of Object.entries(files)) await fsp.writeFile(path.join(this.realRoot, rel), text);
    return true;
  }

  dispose() { try { this.watcher?.close(); } catch {} clearTimeout(this.timer); }
}

module.exports = { Customizations, DEFAULT_SETTINGS };
